#!/bin/bash
# Train -> generate -> evaluate every arm on the 10-image subset, one stage at a time.
#
# Start this only once the GPU is free and scripts/ops/check_tensor_cores.py has passed: it refuses
# to run without a passing gate. Resumable: a stage whose artifacts pass scripts/ops/check_rerun.py
# is skipped. Stops (HALT in campaign.log) on OOM, a NaN loss or artifacts that fail the check; I/O
# deaths are retried. Do not edit this file while it runs: bash reads scripts incrementally.
#   nohup scripts/ops/run_fewshot10.sh > runs/sdxl_cityscapes_fewshot10/logs/runner.out 2>&1 &
set -u -o pipefail
cd "$(dirname "$0")/../.."
source scripts/env.sh
export OMP_NUM_THREADS=16 MKL_NUM_THREADS=16 PYTHONUNBUFFERED=1
export CFG=configs/sdxl_cityscapes_fewshot10.yaml RUN=sdxl_cityscapes_fewshot10 RUN_C1=sdxl_c1_fewshot10
LOGS=runs/$RUN/logs
CAMPAIGN=runs/$RUN/campaign.log
GATE=runs/${RUN}_gate/tensor_core_gate.json
mkdir -p "$LOGS" runs/$RUN_C1/logs

say() { echo "$(date -u +%FT%TZ) $*" >> "$CAMPAIGN"; }
halt() { say "HALT $*"; exit 1; }
check() { python scripts/ops/check_rerun.py "$@" >> "$LOGS/check.log" 2>&1; }

# stage <stage-name> <attempts> <check-args|-> <log> <cmd...>
stage() {
  local name=$1 attempts=$2 check_args=$3 log=$4 rc
  shift 4
  if [ "$check_args" != "-" ] && check $check_args; then say "SKIP $name"; return 0; fi
  for attempt in $(seq 1 "$attempts"); do
    say "START $name attempt=$attempt"
    "$@"
    rc=$?
    say "END $name rc=$rc"
    # The queue scripts rewrite their logs per attempt, so the whole log is this attempt's.
    if grep -aqE "CUDA out of memory|OutOfMemoryError" "$log" 2>/dev/null; then
      halt "$name out of memory"
    fi
    if grep -aqE "loss=(nan|inf)" "$log" 2>/dev/null; then
      halt "$name non-finite loss"
    fi
    if [ "$rc" = 0 ]; then
      if [ "$check_args" != "-" ]; then
        # Twice: the check reads the artifact back from a volume that throws EIO.
        check $check_args || { sleep 60; check $check_args; } || halt "$name artifacts failed the check (see $LOGS/check.log)"
      fi
      return 0
    fi
    say "RETRY $name rc=$rc"
    sleep 60
  done
  halt "$name failed $attempts times"
}

python - "$GATE" <<'PY' || { say "HALT tensor-core gate missing or failed ($GATE)"; exit 1; }
import json, sys
assert json.load(open(sys.argv[1]))["pass"]
PY
ROUTER_GC=$(python -c "import json,sys; print(str(json.load(open(sys.argv[1]))['router_gradient_checkpointing']).lower())" "$GATE")
[ "$ROUTER_GC" = true ] && export ASSEMBLE_SET="model.enable_gradient_checkpointing=true"

# Selections are the full-data run's, unchanged; the CMMD reference is its val export.
for pair in sdxl_cityscapes:$RUN sdxl_c1:$RUN_C1; do
  src=runs/${pair%%:*}/selections dst=runs/${pair##*:}/selections
  mkdir -p "$dst"
  cp -r "$src"/. "$dst"/ && diff -rq "$src" "$dst" > /dev/null || halt "selection copy of ${pair%%:*} does not verify"
done
[ -e runs/$RUN/reference ] || ln -s ../sdxl_cityscapes/reference runs/$RUN/reference
say "CAMPAIGN START"

N1=runs/$RUN/selections/n1/n1_i0.json
foster() {  # run expert [selection]
  scripts/foster_queue.sh "$1:$2${3:+:$3}"
}
for job in "$RUN n1_i0 -" "$RUN n4_i0 $N1" "$RUN n3_i0 $N1" "$RUN n5_i1 $N1" \
           "$RUN n5_i0 -" "$RUN n4_i1 -" "$RUN n4_i2 -" "$RUN n4_i3 -" \
           "$RUN_C1 n4_i0 -" "$RUN_C1 n4_i1 -" "$RUN_C1 n4_i2 -" "$RUN_C1 n4_i3 -"; do
  read -r run expert selection <<< "$job"
  [ "$selection" = "-" ] && selection=""
  stage "foster:$run/$expert" 2 "expert --run $run --name $expert" "runs/$run/logs/foster_$expert.out" \
    foster "$run" "$expert" "$selection"
done

share() { python scripts/share_expert.py --config "$CFG" --name "$RUN" --from "$1" --to "${@:2}"; }
say "START share attempt=1"
for spec in "n4_i1 n5_i2" "n4_i2 n3_i1 n5_i3" "n4_i3 n3_i2 n5_i4"; do
  read -r src targets <<< "$spec"
  missing=()
  for t in $targets; do check expert --run "$RUN" --name "$t" || missing+=("$t"); done
  if [ ${#missing[@]} -gt 0 ]; then
    share "$src" "${missing[@]}" >> "$LOGS/share.out" 2>&1 || halt "share $src -> ${missing[*]} failed"
    for t in "${missing[@]}"; do check expert --run "$RUN" --name "$t" || halt "shared expert $t failed the check"; done
  fi
done
say "END share rc=0"

bundle_dir() {
  case "$1" in
    no1) echo n1-core-n1 ;; no2|c1) echo n4-core-n4 ;; no3) echo n1+n4-core-n4 ;; no4) echo n1+n3+n4-core-n4 ;;
    no5) echo n1+n4+n5-core-n4 ;; no6) echo n3+n4+n5-core-n4 ;; no7) echo n1+n4+n5-core-n5 ;;
    no8) echo n1+n3+n4+n5-core-n4 ;; no9) echo n1+n3+n4+n5-core-n5 ;;
    c2) echo n1+n4-core-n4-disable-n4_i3 ;; c2n2) echo n4-core-n4-disable-n4_i3 ;;
  esac
}
run_of() { [ "$1" = c1 ] && echo "$RUN_C1" || echo "$RUN"; }

ARMS=(no1 no2 no3 c1 no4 no5 no6 no7 no8 no9 c2n2 c2)
for arm in "${ARMS[@]}"; do
  run=$(run_of "$arm")
  stage "assemble:$arm" 2 "bundle --run $run --name $(bundle_dir "$arm")" "runs/$run/logs/assemble_$arm.out" \
    scripts/stage4_assemble_queue.sh "$arm"
done

stage paired_loss 2 - "$LOGS/paired_loss.out" bash -c "scripts/stage3b_paired_loss.sh >> $LOGS/paired_loss.out 2>&1"

for arm in "${ARMS[@]}"; do
  run=$(run_of "$arm")
  stage "generate:$arm" 4 "generate --run $run --name $arm" "runs/$run/logs/gen_$arm.out" \
    env ONLY=generate scripts/stage5_eval_queue.sh "$arm"
  stage "evaluate:$arm" 3 "evaluate --run $run --name $arm" "runs/$run/logs/eval_$arm.out" \
    env ONLY=evaluate scripts/stage5_eval_queue.sh "$arm"
done

say "CAMPAIGN END"
